	@Test
	void rejectedLoaderCannotRewriteTheActiveOwnersResumableInputs() throws Exception {
		Path target = temporaryDirectory.resolve("concurrent-resume-store");
		Path firstInput = temporaryDirectory.resolve("owner.nt");
		Path rejectedInput = temporaryDirectory.resolve("rejected.nt");
		Files.writeString(firstInput, "<urn:owner> <urn:p> <urn:o> .\n");
		Files.writeString(rejectedInput, "<urn:rejected> <urn:p> <urn:o> .\n");
		CountDownLatch ownerStaging = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		AtomicBoolean cancelled = new AtomicBoolean();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		LmdbBulkLoader owner = LmdbBulkLoader.builder(target, config)
				.partitionCount(2)
				.workers(1)
				.cancellationSignal(cancelled::get)
				.progressListener(snapshot -> {
					if (snapshot.phase() == BulkLoadPhase.STAGE_INPUTS && !snapshot.phaseComplete()) {
						ownerStaging.countDown();
						try {
							if (!releaseOwner.await(10, TimeUnit.SECONDS)) {
								throw new AssertionError("test must release the owner");
							}
						} catch (InterruptedException interrupted) {
							Thread.currentThread().interrupt();
							throw new AssertionError(interrupted);
						}
					}
				})
				.build();
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<LmdbBulkLoader.Result> active = executor.submit(() -> owner.load(List.of(
					new LmdbBulkLoader.PathInput(firstInput, RDFFormat.NTRIPLES, "urn:owner:"))));
			try {
				assertThat(ownerStaging.await(10, TimeUnit.SECONDS)).isTrue();
				Path control = BulkLoadWorkspace.controlDirectory(target);
				Properties original = BulkLoadWorkspace.inspect(control);
				assertThat(original).containsEntry("input.source", "PATHS")
						.containsEntry("input.0.path", firstInput.toAbsolutePath().normalize().toString());
				assertThatThrownBy(() -> LmdbBulkLoader.builder(target, config)
						.partitionCount(2)
						.workers(1)
						.build()
						.load(List.of(new LmdbBulkLoader.PathInput(rejectedInput, RDFFormat.NTRIPLES,
								"urn:rejected:"))))
										.isInstanceOf(IOException.class)
										.hasMessageContaining("locked");
				assertThat(BulkLoadWorkspace.inspect(control))
						.as("a rejected contender must not mutate any active resumable metadata")
						.isEqualTo(original);
			} finally {
				cancelled.set(true);
				releaseOwner.countDown();
				assertThatThrownBy(() -> active.get(10, TimeUnit.SECONDS))
						.isInstanceOf(ExecutionException.class)
						.hasCauseInstanceOf(CancellationException.class);
			}
		}
		LmdbBulkLoader.builder(target, config).partitionCount(2).workers(1).build().resume();
		assertThat(readStatements(target)).extracting(statement -> statement.getSubject().stringValue())
				.containsExactly("urn:owner");
	}

	@Test
	void preservesChecksummedPromotedArtifactsUntilRecoveryFinishes() throws Exception {
		Path target = Files.createDirectory(temporaryDirectory.resolve("recoverable-store"));
		String generationName = ".lmdb-bulk-generation-recovery-test";
		Path artifact = target.resolve("values");
		byte[] artifactBytes = "complete-value-store".getBytes(StandardCharsets.UTF_8);
		Files.write(artifact, artifactBytes);

		Properties marker = new Properties();
		marker.setProperty("version", "2");
		marker.setProperty("generation", generationName);
		storeProperties(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME), marker);

		Properties manifest = new Properties();
		manifest.setProperty("version", "2");
		manifest.setProperty("generation", generationName);
		manifest.setProperty("artifact.count", "1");
		manifest.setProperty("artifact.0", "values");
		manifest.setProperty("artifact.0.type", "file");
		manifest.setProperty("artifact.0.size", Long.toString(artifactBytes.length));
		manifest.setProperty("artifact.0.sha256",
				HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(artifactBytes)));
		manifest.setProperty("result.parsed-statements", "3");
		manifest.setProperty("result.stored-statements", "2");
		manifest.setProperty("result.persisted-values", "4");
		manifest.setProperty("result.inline-values", "1");
		manifest.setProperty("result.temporary-bytes", "1024");
		manifest.setProperty("result.elapsed-millis", "15");
		manifest.setProperty("result.map-growth-count", "2");
		storeProperties(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME), manifest);

		try (LmdbBulkLoadGeneration recovered = LmdbBulkLoadGeneration.create(target)) {
			assertThat(artifact).hasBinaryContent(artifactBytes);
			assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).exists();

			Method finish = LmdbBulkLoadGeneration.class.getDeclaredMethod("finishRecoveredPublication");
			finish.setAccessible(true);
			finish.invoke(recovered);
		}

		assertThat(artifact).hasBinaryContent(artifactBytes);
		assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).doesNotExist();
		assertThat(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)).doesNotExist();
	}

	@Test
	void resumesAPartiallyPromotedNativeStoreWithoutReadingInputAgain() throws Exception {
		String input = """
				<urn:s> <urn:p> <urn:o> .
				<urn:s2> <urn:p> "value" <urn:g> .
				""";
		Path target = temporaryDirectory.resolve("partially-promoted-store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");

		assertThatThrownBy(() -> LmdbBulkLoader.builder(target, config)
				.partitionCount(4)
				.publicationHook((index, source, destination) -> {
					if (index == 1) {
						throw new IOException("injected publication failure");
					}
				})
				.build()
				.load(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)), "urn:bulk-test:",
						RDFFormat.NQUADS))
								.isInstanceOf(IOException.class)
								.hasMessageContaining("injected publication failure");
		assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).exists();
		assertThat(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)).exists();

		LmdbBulkLoader.Result result = LmdbBulkLoader.builder(target, config)
				.partitionCount(4)
				.build()
				.load(new ReadFailingInputStream(), "urn:must-not-be-read:", RDFFormat.NQUADS);

		assertThat(result.parsedStatements()).isEqualTo(2);
		assertThat(result.storedStatements()).isEqualTo(2);
		assertThat(readStatements(target)).hasSize(2);
		assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).doesNotExist();
		assertThat(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)).doesNotExist();
	}

