	@Test
	void reopensCollisionAndRdfStarValuesForIncrementalWrites() throws Exception {
		String input = """
				<urn:s1> <urn:p> "plumless--fresh-collision-value" .
				<urn:s2> <urn:p> "buckeroo--fresh-collision-value" .
				<urn:owner> <urn:quoted> <<( <urn:inner-subject> <urn:inner-predicate> "inner"@EN )>> .
				""";
		Path target = temporaryDirectory.resolve("incremental-after-bulk-store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		config.setValueHashCacheEnabled(true);
		config.setTripleTermIndexes("spoc,cspo,posc");
		LmdbBulkLoader.builder(target, config)
				.partitionCount(4)
				.memoryBudgetBytes(32 * 1024)
				.build()
				.load(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)), "urn:bulk-test:",
						RDFFormat.NQUADS);

		var valueFactory = SimpleValueFactory.getInstance();
		Value quoted = valueFactory.createTripleTerm(valueFactory.createIRI("urn:inner-subject"),
				valueFactory.createIRI("urn:inner-predicate"), valueFactory.createLiteral("inner", "en"));
		SailRepository repository = new SailRepository(new LmdbStore(target.toFile(), config));
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				assertThat(connection.hasStatement(valueFactory.createIRI("urn:s1"), valueFactory.createIRI("urn:p"),
						valueFactory.createLiteral("plumless--fresh-collision-value"), false)).isTrue();
				assertThat(connection.hasStatement(valueFactory.createIRI("urn:s2"), valueFactory.createIRI("urn:p"),
						valueFactory.createLiteral("buckeroo--fresh-collision-value"), false)).isTrue();
				assertThat(connection.hasStatement(valueFactory.createIRI("urn:owner"),
						valueFactory.createIRI("urn:quoted"), quoted, false)).isTrue();

				connection.add(valueFactory.createIRI("urn:new-owner"), valueFactory.createIRI("urn:quoted"), quoted);
				connection.add(valueFactory.createIRI("urn:new-subject"), valueFactory.createIRI("urn:new-predicate"),
						valueFactory.createLiteral("new-value", valueFactory.createIRI("urn:new-datatype")));
				assertThat(connection.size()).isEqualTo(5);
			}
		} finally {
			repository.shutDown();
		}

		assertThat(readStatements(target)).hasSize(5);
	}

