	@Test
	void bulkLoadedStoreMatchesTransactionallyLoadedStore() throws Exception {
		StringBuilder input = new StringBuilder("""
				_:alice <urn:eq:name> "Alice"@en .
				_:alice <urn:eq:knows> _:bob <urn:eq:graph:a> .
				_:bob <urn:eq:name> "Bob"@en-gb <urn:eq:graph:b> .
				<urn:eq:book> <urn:eq:says> <<( <urn:eq:alice> <urn:eq:knows> <urn:eq:bob> )>> .
				<urn:eq:book> <urn:eq:says> <<( <urn:eq:alice> <urn:eq:knows> <urn:eq:bob> )>> .
				<urn:eq:s> <urn:eq:p> "plain" .
				<urn:eq:s> <urn:eq:p> "plain" <urn:eq:graph:a> .
				<urn:eq:s> <urn:eq:p> "typed"^^<urn:eq:datatype> .
				""");
		for (int index = 0; index < 3_000; index++) {
			String graph = index % 3 == 0 ? "" : " <urn:eq:graph:" + (index % 3 == 1 ? "a" : "b") + ">";
			input.append("<urn:eq:subject:")
					.append(index % 701)
					.append("> <urn:eq:predicate:")
					.append(index % 23)
					.append("> ");
			switch (index % 5) {
			case 0 -> input.append("<urn:eq:object:").append(index % 97).append('>');
			case 1 -> input.append('"').append(index).append("\"^^<http://www.w3.org/2001/XMLSchema#integer>");
			case 2 -> input.append("\"label ").append(index % 211).append("\"@en");
			case 3 -> input.append('"').append("long-").append(index).append('-').append("y".repeat(300)).append('"');
			default -> input.append("_:node").append(index % 41);
			}
			input.append(graph).append(" .\n");
		}
		byte[] bytes = input.toString().getBytes(StandardCharsets.UTF_8);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		Path bulkTarget = temporaryDirectory.resolve("equivalence-bulk-store");
		Path transactionalTarget = temporaryDirectory.resolve("equivalence-transactional-store");

		LmdbBulkLoader.builder(bulkTarget, config)
				.partitionCount(4)
				.memoryBudgetBytes(1024 * 1024)
				.maxOpenFiles(8)
				.workers(4)
				.build()
				.load(new ByteArrayInputStream(bytes), "urn:eq:", RDFFormat.NQUADS);
		SailRepository transactional = new SailRepository(new LmdbStore(transactionalTarget.toFile(), config));
		transactional.init();
		try (RepositoryConnection connection = transactional.getConnection()) {
			connection.begin();
			connection.add(new ByteArrayInputStream(bytes), "urn:eq:", RDFFormat.NQUADS);
			connection.commit();
		} finally {
			transactional.shutDown();
		}

		Set<Statement> bulkStatements = readStatements(bulkTarget);
		Set<Statement> transactionalStatements = readStatements(transactionalTarget);
		assertThat(bulkStatements).hasSameSizeAs(transactionalStatements);
		assertThat(Models.isomorphic(bulkStatements, transactionalStatements)).isTrue();
		assertThat(countQueries(bulkTarget, config)).isEqualTo(countQueries(transactionalTarget, config));
	}

	@Test
	void parallelStagingAcrossManyBlocksMatchesSerialStaging() throws Exception {
		StringBuilder input = new StringBuilder();
		for (int index = 0; index < 10_000; index++) {
			String graph = index % 3 == 0 ? "" : " <urn:par:graph:" + index % 7 + ">";
			input.append(index % 11 == 0 ? "_:node" + index % 13 : "<urn:par:subject:" + index % 3_001 + ">")
					.append(" <urn:par:predicate:")
					.append(index % 17)
					.append("> ");
			if (index % 2 == 0) {
				input.append("\"value ").append(index % 509).append("\"@en");
			} else {
				input.append("<urn:par:object:").append(index % 701).append('>');
			}
			input.append(graph).append(index % 5 == 0 ? " .\r\n" : " .\n");
		}
		byte[] bytes = input.toString().getBytes(StandardCharsets.UTF_8);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		Path serialTarget = temporaryDirectory.resolve("serial-staging-store");
		Path parallelTarget = temporaryDirectory.resolve("parallel-staging-store");

		LmdbBulkLoader serial = LmdbBulkLoader.builder(serialTarget, config)
				.partitionCount(4)
				.memoryBudgetBytes(64L * 1024 * 1024)
				.maxOpenFiles(64)
				.workers(1)
				.build();
		// 4 KiB blocks split the 0.9 MB input into a few hundred blocks committed out of completion order.
		LmdbBulkLoader parallel = LmdbBulkLoader.builder(parallelTarget, config)
				.partitionCount(4)
				.memoryBudgetBytes(64L * 1024 * 1024)
				.maxOpenFiles(64)
				.workers(8)
				.stagingBlockBytes(4 * 1024)
				.build();
		assertThat(ParallelStager.applicable(serial, List.of(RDFFormat.NQUADS))).isFalse();
		assertThat(ParallelStager.applicable(parallel, List.of(RDFFormat.NQUADS))).isTrue();

		LmdbBulkLoader.Result serialResult = serial.load(new ByteArrayInputStream(bytes), "urn:par:",
				RDFFormat.NQUADS);
		LmdbBulkLoader.Result parallelResult = parallel.load(new ByteArrayInputStream(bytes), "urn:par:",
				RDFFormat.NQUADS);

		assertThat(parallelResult.parsedStatements()).isEqualTo(10_000L).isEqualTo(serialResult.parsedStatements());
		assertThat(parallelResult.storedStatements()).isEqualTo(serialResult.storedStatements());
		assertThat(readValueIds(parallelTarget, config)).isEqualTo(readValueIds(serialTarget, config));
		assertThat(readStatements(parallelTarget)).isEqualTo(readStatements(serialTarget));
	}

