	@Test
	void blankNodeLabelsAreScopedPerFileInMultiFileLoads() throws Exception {
		Path first = temporaryDirectory.resolve("first-bnodes.nq");
		Path second = temporaryDirectory.resolve("second-bnodes.nq");
		Files.writeString(first, "_:b1 <urn:bn:name> \"first\" .\n_:b1 <urn:bn:in> <urn:bn:graph> <urn:bn:g> .\n");
		Files.writeString(second, "_:b1 <urn:bn:name> \"second\" .\n_:b1 <urn:bn:in> <urn:bn:graph> <urn:bn:g> .\n");
		List<LmdbBulkLoader.PathInput> inputs = List.of(
				new LmdbBulkLoader.PathInput(first, RDFFormat.NQUADS, "urn:bn:first"),
				new LmdbBulkLoader.PathInput(second, RDFFormat.NQUADS, "urn:bn:second"));
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		Map<String, Set<Statement>> loaded = new HashMap<>();
		for (String variant : List.of("serial-fast", "parallel-fast", "rio")) {
			Path target = temporaryDirectory.resolve("bnode-scope-" + variant);
			LmdbBulkLoader.Builder builder = LmdbBulkLoader.builder(target, config).partitionCount(4);
			switch (variant) {
			case "serial-fast" -> builder.workers(1).parserMode(LmdbBulkLoader.ParserMode.FAST);
			case "parallel-fast" -> builder.workers(4)
					.memoryBudgetBytes(64L * 1024 * 1024)
					.maxOpenFiles(64)
					.parserMode(LmdbBulkLoader.ParserMode.FAST);
			default -> builder.parserMode(LmdbBulkLoader.ParserMode.RIO);
			}
			LmdbBulkLoader.Result result = builder.build().load(inputs);
			assertThat(result.storedStatements()).as(variant).isEqualTo(4L);
			Set<Statement> statements = readStatements(target);
			assertThat(statements.stream().map(Statement::getSubject).distinct().count()).as(variant).isEqualTo(2L);
			loaded.put(variant, statements);
		}
		assertThat(Models.isomorphic(loaded.get("serial-fast"), loaded.get("rio"))).isTrue();
		assertThat(Models.isomorphic(loaded.get("parallel-fast"), loaded.get("rio"))).isTrue();
	}

